PAYLOAD=''
import base64,zipfile,io,os,sys,json,hashlib,subprocess,time
from pathlib import Path
from PIL import Image,ImageOps
import torch
zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))).extractall('/kaggle/working')
os.chdir('/kaggle/working');sys.path.insert(0,os.getcwd())
from faceforge.model import Generator
from faceforge.inference import latent
subprocess.check_call([sys.executable,'-m','pip','install','clean-fid==0.1.35','--no-deps','-q'])
from cleanfid import fid
root=Path('/kaggle/input');source=sorted(p for p in root.rglob('*.jpg'))[:10000]
assert len(source)==10000
manifest_paths=list(root.rglob('manifest.json'))
reference=None
for p in manifest_paths:
 try:
  a=json.loads(p.read_text())
  if len(a['rows'])==10000: reference=a;break
 except Exception:pass
assert reference is not None
real=Path('real');real.mkdir(exist_ok=True)
rows=[r for r in reference['rows'] if r['split']=='test']
assert len(rows)==1000
for i,r in enumerate(rows):
 idx=int(Path(r['path']).stem)
 p=source[idx]
 assert hashlib.sha256(p.read_bytes()).hexdigest()==r['sha256']
 with Image.open(p) as im:
  im=ImageOps.exif_transpose(im).convert('RGB');im=ImageOps.fit(im,(178,178),centering=(.5,.5));im=im.resize((64,64),Image.Resampling.LANCZOS);im.save(real/f'{i:04}.png')
results={}
for label,needle in [('recovery','faceforge-recovery-10k'),('extended','faceforge-extended-dcgan')]:
 paths=[p for p in root.rglob('checkpoint.pt') if needle in str(p)]
 assert len(paths)==1,(label,paths)
 c=torch.load(paths[0],map_location='cpu',weights_only=False);cfg=c['config'];g=Generator(cfg['z_dim'],cfg['width']).cuda().eval();g.load_state_dict(c['generator']);fake=Path(label);fake.mkdir(exist_ok=True)
 z=latent(20261120,1000,cfg['z_dim']) if False else torch.randn(1000,cfg['z_dim'],1,1,generator=torch.Generator().manual_seed(20261120))
 t=time.time()
 with torch.inference_mode():
  for start in range(0,1000,64):
   imgs=g(z[start:start+64].cuda()).cpu().add(1).div(2).clamp(0,1).mul(255).round().byte()
   for j,x in enumerate(imgs): Image.fromarray(x.permute(1,2,0).numpy()).save(fake/f'{start+j:04}.png')
 latency=(time.time()-t)/1000
 score_fid=fid.compute_fid(str(real),str(fake),mode='clean',num_workers=0,device=torch.device('cuda'))
 score_kid=fid.compute_kid(str(real),str(fake),mode='clean',num_workers=0,device=torch.device('cuda'))
 results[label]={'fid':score_fid,'kid':score_kid,'latency_s_per_image':latency,'checkpoint':str(paths[0]),'n_real':1000,'n_fake':1000}
 print(label,results[label],flush=True)
Path('evaluation.json').write_text(json.dumps(results,indent=2));print('FINISHED',flush=True)
